const rows = $('Fetch Config').all();
const config = {}

rows.forEach(row => {
  config[row.json.key] = row.json.value;
});

try {
  config.candidate_profile = JSON.parse(config.candidate_profile);
} catch(e) {
  config.candidate_profile = {};
}

config.cv_language = config.cv_language || 'de';

try {
  config.role_type_scores = JSON.parse(config.role_type_scores);
} catch(e) {
  config.role_type_scores = {};
}

return [{ json: config }]

const raw = $('Guardrails').first().json.guardrailsInput || '';

if (!raw || raw.trim().length < 50) {
  throw new Error('Input vacío o demasiado corto.');
}

function detectLanguage(text) {
  const input = String(text || "").trim();

  if (!input) {
    return {
      language: "unknown",
      confidence: 0,
      scores: { german: 0, english: 0 }
    };
  }

  const lower = input.toLowerCase();

  // Common markers
  const germanWords = [
    "der", "die", "das", "und", "ist", "nicht", "ich", "du", "wir", "ihr",
    "sie", "mit", "für", "auf", "ein", "eine", "einer", "einem", "den",
    "dem", "des", "wie", "was", "aber", "auch", "noch", "nur", "schon",
    "wenn", "dann", "oder", "hat", "haben", "war", "waren", "zum", "zur"
  ];

  const englishWords = [
    "the", "and", "is", "not", "i", "you", "we", "they", "with", "for",
    "on", "a", "an", "this", "that", "of", "to", "in", "as", "but",
    "also", "still", "only", "already", "if", "then", "or", "has", "have",
    "had", "was", "were", "be", "are", "from", "it"
  ];

  let germanScore = 0;
  let englishScore = 0;

  // Strong German hints
  if (/[äöüß]/.test(lower)) germanScore += 4;
  if (/\b(nicht|ich|und|für|mit|eine|einer|einem|der|die|das)\b/.test(lower)) germanScore += 3;
  if (/(sch|ung|keit|lich|chen)\b/.test(lower)) germanScore += 2;

  // Strong English hints
  if (/\b(the|and|with|this|that|have|from|are|was|were)\b/.test(lower)) englishScore += 3;
  if (/\b(ing|tion|ness|ment)\b/.test(lower)) englishScore += 1;

  // Count stopwords
  for (const word of germanWords) {
    const matches = lower.match(new RegExp(`\\b${word}\\b`, "g"));
    if (matches) germanScore += matches.length;
  }

  for (const word of englishWords) {
    const matches = lower.match(new RegExp(`\\b${word}\\b`, "g"));
    if (matches) englishScore += matches.length;
  }

  let language = "unknown";
  if (germanScore > englishScore) language = "de";
  else if (englishScore > germanScore) language = "en";

  const total = germanScore + englishScore;
  const confidence = total === 0
    ? 0
    : Number((Math.max(germanScore, englishScore) / total).toFixed(2));

  return {
    language,
    confidence,
    scores: {
      german: germanScore,
      english: englishScore
    }
  };
}

return [{
  json: {
    job_posting_wrapped: `<job_posting>\n${raw.trim()}\n</job_posting>`,
    job_post_language: detectLanguage(raw),
    raw_input: raw,
    char_count: raw.length,
    company_detected: null,   // el Analyzer lo extrae
    search_query: null        // se construye después del Analyzer
  }
}];

