function stripMarkdown(text) {
  return text
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/\*(.+?)\*/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^[-*+]\s+/gm, '')
    .replace(/`(.+?)`/g, '$1')
    .replace(/\[(.+?)\]\(.+?\)/g, '$1')
    .trim();
}

function computeDiff(original, modified) {
  const origLines = original.split('\n').filter(l => l.trim());
  const modLines  = modified.split('\n').filter(l => l.trim());
  const m = origLines.length, n = modLines.length;
  const dp = Array.from({length: m+1}, () => new Array(n+1).fill(0));

  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] = origLines[i-1] === modLines[j-1]
        ? dp[i-1][j-1] + 1
        : Math.max(dp[i-1][j], dp[i][j-1]);

  const result = [];
  let i = m, j = n;
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && origLines[i-1] === modLines[j-1]) {
      result.unshift('  ' + origLines[i-1]);
      i--; j--;
    } else if (j > 0 && (i === 0 || dp[i][j-1] >= dp[i-1][j])) {
      result.unshift('+ ' + modLines[j-1]);
      j--;
    } else {
      result.unshift('- ' + origLines[i-1]);
      i--;
    }
  }
  return result.join('\n');
}

const cvMarkdown = $('CV Rewriter').first().json.text || '';
const cvOriginal = $('Call CV Translation Cache').first().json.cv_text_final || '';

const origStripped = stripMarkdown(cvOriginal);
const modStripped  = stripMarkdown(cvMarkdown);

const cvDiff = computeDiff(origStripped, modStripped);

return [{ json: { cv_diff: cvDiff, cv_markdown: cvMarkdown } }];

const instructions = $('Call CV Tailoring Planner').first().json.output.cv_anpassungen;
let cv = $('Call CV Translation Cache').item.json.cv_text_final.replace(/\r\n/g, '\n');

const failed = [];

for (const inst of instructions.filter(i => ['ENTFERNEN','REMOVE'].includes(i.aktion))) {
  const original = inst.original.trim();
  if (cv.includes(original)) {
    cv = cv.replace('\n' + original, '').replace(original + '\n', '').replace(original, '');
  } else {
    failed.push({ bereich: inst.bereich, error: 'MATCH_NOT_FOUND' });
  }
}

const remaining = instructions.filter(i => !['ENTFERNEN','REMOVE'].includes(i.aktion));

return [{ json: { cv_half_modified: cv, remaining_instructions: remaining, failed_instructions: failed } }];

